--- from: Assets/BundleResources/Prefabs/Friend/FriendPromptDialog.prefab
---@class FriendPrompt
---@field Env                           	FriendPrompt                            
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field TxtTimeLetter                 	TMPro.TextMeshProUGUI                   
---@field FillLetter                    	UnityEngine.UI.Image                    
---@field TxtName                       	UnityEngine.UI.Text                     
---@field Fill                          	UnityEngine.UI.Image                    
---@field TxtTime                       	TMPro.TextMeshProUGUI                   
---@field CommonPlayerHeadNode          	Engine.Modules.LuaBehaviour             
---@field BtnArrow                      	UnityEngine.UI.Button                   
---@field First                         	UnityEngine.RectTransform               
---@field BtnLetter                     	UnityEngine.UI.Button                   
---@field Animation_Root                	UnityEngine.Animation                   
---@field RT_Bg                         	UnityEngine.RectTransform               
local FriendPrompt = Class("FriendPrompt")
function FriendPrompt:__init()
    self.data = {}
    self.pvpWaitTime = nil
end

function FriendPrompt:__delete()
    self.controller = nil
    self.data = nil
    self.pvpWaitTime = nil
end

function FriendPrompt:Awake()

    -- SpriteAtlasManager.Instance():Retain(atlasName)
    self.EventFriendPVPPrompt = Events.AddListener(Constants.EventNames.FriendPVPPrompt, Bind(self, self.ReceiveInvite))
    self.EventFriendPVPPromptBeCancelled = Events.AddListener(Constants.EventNames.FriendPVPPromptBeCancelled, Bind(self, self.OnCancel))
    self.pvpWaitTime = friendComponent:InviteWaitTime()--好友参数表中的好友切磋邀请待处理时间（秒）
    if isNull(self.CommonPlayerHeadNode.Env) then
        self.CommonPlayerHeadNode:Init()
    end

    self:DirectionHide()
    self:ResetDefaultStatus()

    -- 点击前往
    SetButtonAction(self.BtnArrow, function()
        if not isNull(self.data) then
            if checkInt(self.data.time) > 0 then
                
                local screenId = UIModule.CurrentScreen.Argument.id
                if screenId == Constants.UITypeIds.UIMaidCoffeeEnterScene then
                    GameUtils.Toast(localize("在餐厅中无法接受好友切磋"))
                    return
                end
                
                if friendComponent:HasPVPTeam() then
                    ---@type TeamComponent
                    local teamComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.TeamComponent)
                    teamComponent:SetTeamReq(Constants.SpecialQuestId.FriendPVPId, function()
                        self:DirectionHide()
                        self:ResetDefaultStatus()
                        -- 如果有编队，直接接受
                        friendComponent:ReplyInvite(1)
                    end)
                else
                    -- 如果没有编队，先去编队
                    GameUtils.Toast(localize("您还没有编队，请先编个队吧"))
                    if not friendComponent:IsInPVPFormation() then
                        local closeHomeView = GameUtils.IsInMainHomeView() and {{id = Constants.UITypeIds.UIHomeView}} or nil
                        UIModule.OpenDialog({ id = Constants.UITypeIds.UIFightTeamChoose, parameters = { levelId = Constants.SpecialQuestId.FriendPVPId, teamIndex = 1 } }, closeHomeView)
                    end
                end
            end
        end
    end)

    -- 点击信封，打开邀请函界面
    SetButtonAction(self.BtnLetter, function ()
        if not isNull(self.data) then
            if checkInt(self.data.time) > 0 then
                KTool.SetActive(self.BtnLetter, false)
                UIModule.OpenDialog({
                    id = Constants.UITypeIds.FriendInvitationReceive,
                    parameters = {
                        data = self.data,--数据
                        responseFunc = function()--接受或拒绝的回调
                            self:DirectionHide()
                            self:ResetDefaultStatus()
                        end,
                        backFunc = function()--点击空白关闭的回调
                            KTool.SetActive(self.BtnLetter, true)
                        end
                    }
                })
            end
        end
    end)
end

---长链接收到pvp邀请
---@param friendId number 玩家id  用这个id去好友列表获取相应信息
function FriendPrompt:ReceiveInvite(friendInfo)
    if KNManager.isPaused then--屏蔽切换到后台
        friendComponent:ReplyInvite(2)
        return
    end
    if isNull(friendInfo) then
        friendComponent:ReplyInvite(2)
        return
    end
    --region scene屏蔽
    local excludeScene = {
        Constants.UITypeIds.BattleScene,
        Constants.UITypeIds.WorldBossEntry,
        --Constants.UITypeIds.PatrolEntryDialog,
        --Constants.UITypeIds.PatrolMainDialog,
        --活动副本
        --每日定时副本
    }
    local screenId = UIModule.CurrentScreen.Argument.id
    if table.keyof(excludeScene, screenId) ~= nil then--无法接受邀请，返回拒绝
        friendComponent:ReplyInvite(2)
        return
    end
    --endregion
    --region dialog屏蔽
    local excludeDialog = {
        Constants.UITypeIds.PatrolEntryDialog,
        Constants.UITypeIds.PatrolMainDialog,
        Constants.UITypeIds.LadderCompetionMainDialog,
    }
    local dialogs = UIModule.CurrentScreen.dialogs
    local dialogsCount = dialogs.Count

    for i = 0, dialogs.Count - 1 do
        local dialog = dialogs[i]
        local dialogId = dialog.Argument.id
        if table.isContain(excludeDialog, dialogId) then
            friendComponent:ReplyInvite(2)
            return
        end
    end
    --endregion
    
    -- 屏蔽歼灭战
    if GameUtils.IsInAnnihilation() then
        friendComponent:ReplyInvite(2)
        return
    end

    GameUtils.Request(
            Interfaces.FriendHome,
            {},
            function(request, response)
                if checkInt(response.errCode) == 0 then
                    friendComponent:InitialDojo(response.data)--初始化好友数据
                    local friendId = checkNumber(friendInfo.playerId)
                    self.data = friendComponent:GetFriendInfo(friendId)
                    self.data["time"] = DeepCopy(self.pvpWaitTime)--和哲臣确认读表写死
                    if isNull(self.data) then
                        return
                    end
                    self.controller.transform:SetAsLastSibling()
                    self:AnimationShow()
                    -- CfUtils.PlayAnimator(self.First, "Show")
                    --KTool.SetActive(self.First, true)
                    self.TxtName.text = self.data.name
                    self.CommonPlayerHeadNode.Env:FreshAvatarFrame(self.data.avatar, self.data.avatarFrame)
                    self:StartLeftSecond(self.data.time)
                    -- 没有编队时显示空提示
                    KTool.SetActive(self.BtnArrow.transform:Find("TxtEmpty"), not friendComponent:HasPVPTeam())
                end
            end
    )
end

---开始倒计时
function FriendPrompt:StartLeftSecond(leftTime)
    self:StopTimer()
    self.timer = CDTimerModule:AddCD(1, function (count, id)
        if count == 0 then
            self:DirectionHide()
            self:ResetDefaultStatus()
            friendComponent:ReplyInvite(3)
        else
            self.data.time = count
            self.TxtTime.text = count
            self.Fill.fillAmount = count / leftTime
            self.TxtTimeLetter.text = count
            self.FillLetter.fillAmount = count / leftTime
        end
    end, leftTime, true, true, true)
end

function FriendPrompt:ResetDefaultStatus()
    self:StopTimer()
    self.data = nil
    CoStop(self.coLetter)
end

function FriendPrompt:StopTimer()
    if not isNull(self.timer) then
        CDTimerModule:RemoveCD(self.timer)
        self.timer = nil
    end
end

function FriendPrompt:OnDestroy()
    -- SpriteAtlasManager.Instance():Release(atlasName)
    Events.RemoveListener(Constants.EventNames.FriendPVPPrompt, self.EventFriendPVPPrompt)
    Events.RemoveListener(Constants.EventNames.FriendPVPPromptBeCancelled, self.EventFriendPVPPromptBeCancelled)
    self:StopTimer()
    CoStop(self.coLetter)
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end

--- 显示邀请的状态
function FriendPrompt:AnimationShow()
    KTool.SetActive(self.Animation_Root.gameObject, true)
    -- KTool.SetActive(self.First.gameObject, true)
    self.Animation_Root:Play(ShowAnimationName)
    self.coLetter = CoStart(function()
        CoYield(2)
        self:AnimationLetter()
    end)
end

function FriendPrompt:AnimationLetter()
    KTool.SetActive(self.Animation_Root.gameObject, true)
    self.Animation_Root:Play(BackAnimationName)
end

function FriendPrompt:DirectionHide()
    KTool.SetActive(self.Animation_Root.gameObject, false)
end

function FriendPrompt:OnCancel()
    self:DirectionHide()
    self:ResetDefaultStatus()
end

return FriendPrompt